av_ego.code:
// AV stack · SENSE / state estimation ("localization" layer).
// Publishes the ego state on the shared blackboard `input.av.ego` for all later stages.
// Owns the simulated clock (state.t) so no downstream stage needs a wall clock.
function transform(input, dt, params, state, api) {
  var av = input.av || (input.av = {})
  if (state.t === undefined) {
    state.t = 0
    state.speedF = 0
    state.prevSpeed = 0
    state.accelF = 0
  }
  state.t += dt
  var up = api.getUpVector(input.rotation)
  var fwd = api.vec.normalize(api.vec.projectOntoPlane(api.getForwardVector(input.rotation), up))
  var left = api.vec.normalize(api.vec.cross(up, fwd))
  var speed = api.vec.getForwardSpeed(input.velocity, fwd)
  var yawRate = api.vec.dot(input.angularVelocity, up)
  var a = dt > 1e-6 ? (speed - state.prevSpeed) / dt : 0
  state.prevSpeed = speed
  state.accelF += (a - state.accelF) * Math.min(1, dt * 8)
  state.speedF += (speed - state.speedF) * Math.min(1, dt * 20)
  av.ego = {
    t: state.t,
    dt: dt,
    pos: input.position,
    fwd: fwd,
    left: left,
    up: up,
    speed: speed,
    speedF: state.speedF,
    accel: state.accelF,
    yawRate: yawRate,
    kappa: Math.abs(speed) > 1.5 ? yawRate / speed : 0,
  }
  api.watch('av.speed', Math.round(speed * 10) / 10)
  return {}
}

av_perception.code:
// AV stack · SENSE / perception.
// 360° range-scan ring (lidar-like, mounted at the vehicle centre, rays start on the hull)
// + obstacle memory ("local costmap") so the planners also know what is behind / beside.
// Publishes: av.scan {angles, ranges, range}, av.points [[x,z],...] (world), av.rearClear.
// params: rayCount, fovDeg, sensorRange, memoryTtl, memoryCell, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var n = params.rayCount || 72
  var fov = ((params.fovDeg || 360) * Math.PI) / 180
  var range = params.sensorRange || 24
  var ttl = params.memoryTtl != null ? params.memoryTtl : 15
  var cell = params.memoryCell || 0.5
  var hl = (params.vehicleLength || 4) / 2 + 0.15
  var hw = (params.vehicleWidth || 2) / 2 + 0.15
  if (!state.mem) state.mem = {}
  var mem = state.mem
  var pos = input.position
  var full = fov >= 2 * Math.PI - 1e-3
  var angles = []
  var ranges = []
  var rearClear = params.rearRange || 8
  for (var i = 0; i < n; i++) {
    var th = full ? -Math.PI + (2 * Math.PI * i) / n : n === 1 ? 0 : -fov / 2 + (fov * i) / (n - 1)
    var c = Math.cos(th)
    var s = Math.sin(th)
    var dir = [
      e.fwd[0] * c + e.left[0] * s,
      e.fwd[1] * c + e.left[1] * s,
      e.fwd[2] * c + e.left[2] * s,
    ]
    // start just outside the hull rectangle along this ray
    var tHull = Math.min(Math.abs(c) > 1e-6 ? hl / Math.abs(c) : 1e9, Math.abs(s) > 1e-6 ? hw / Math.abs(s) : 1e9)
    var origin = api.vec.offsetAlong(pos, dir, tHull)
    var r = api.raycast(origin, dir, range, { visualize: false })
    angles.push(th)
    if (r.hit) {
      ranges.push(r.distance)
      var hx = origin[0] + dir[0] * r.distance
      var hz = origin[2] + dir[2] * r.distance
      mem[Math.round(hx / cell) + ',' + Math.round(hz / cell)] = { x: hx, z: hz, t: e.t }
      if (c < -0.9 && r.distance < rearClear) rearClear = r.distance
    } else {
      ranges.push(range)
    }
  }
  var pts = []
  var keys = Object.keys(mem)
  for (var k = 0; k < keys.length; k++) {
    var m = mem[keys[k]]
    if (e.t - m.t > ttl) delete mem[keys[k]]
    else pts.push([m.x, m.z])
  }
  av.scan = { angles: angles, ranges: ranges, range: range }
  av.points = pts
  av.rearClear = rearClear
  return {}
}

av_motion_planner.code:
// AV stack · PLAN / local motion planner (sampling-based, dynamic-window style).
// Rolls out constant-curvature arcs of the bicycle model, checks the swept vehicle footprint
// against the costmap, and picks the arc with the best progress / clearance / smoothness cost.
// Publishes av.plan {kappa, free, freeSoft, blocked, horizon}.
// params: vehicleWidth, vehicleLength, safetyMargin, softMargin, maxCurvature, arcCount,
//         horizonMin, horizonGain, horizonMax, wProgress, wHeading, wFree, wSoft, wSmooth, minFree
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) {
    av.plan = { kappa: 0, free: 0, freeSoft: 0, blocked: false, horizon: 0, noGoal: true }
    return {}
  }
  var pos = input.position
  var gdx = tgt[0] - pos[0]
  var gdz = tgt[2] - pos[2]
  var gx = gdx * e.fwd[0] + gdz * e.fwd[2]
  var gy = gdx * e.left[0] + gdz * e.left[2]
  var goalDist = Math.sqrt(gx * gx + gy * gy)
  av.goal = { x: tgt[0], z: tgt[2], dist: goalDist, fx: gx, fy: gy }

  var margin = params.safetyMargin != null ? params.safetyMargin : 0.5
  var soft = params.softMargin != null ? params.softMargin : 1.1
  var halfW = (params.vehicleWidth || 2) / 2 + margin
  var halfL = (params.vehicleLength || 4) / 2 + margin
  var kmax = params.maxCurvature || 0.115
  var count = params.arcCount || 41
  var hMin = params.horizonMin != null ? params.horizonMin : 9
  var hMax = params.horizonMax != null ? params.horizonMax : 20
  var H = Math.min(hMax, hMin + (params.horizonGain != null ? params.horizonGain : 0.9) * Math.max(0, e.speedF))
  var wProg = params.wProgress != null ? params.wProgress : 1.0
  var wHead = params.wHeading != null ? params.wHeading : 2.0
  var wFree = params.wFree != null ? params.wFree : 14
  var wSoft = params.wSoft != null ? params.wSoft : 5
  var wSmooth = params.wSmooth != null ? params.wSmooth : 2.5
  var minFree = params.minFree != null ? params.minFree : 4.5
  var ds = 0.75

  // costmap into ego frame
  var pts = av.points || []
  var ox = []
  var oy = []
  for (var i = 0; i < pts.length; i++) {
    var dx = pts[i][0] - pos[0]
    var dz = pts[i][1] - pos[2]
    var px = dx * e.fwd[0] + dz * e.fwd[2]
    var py = dx * e.left[0] + dz * e.left[2]
    if (px > -halfL - soft - 1 && px < H + halfL + soft + 1 && py > -H - 3 && py < H + 3) {
      ox.push(px)
      oy.push(py)
    }
  }

  function freeLength(kappa, hw, hl) {
    var sMax = H
    for (var s = 0; s <= sMax; s += ds) {
      var th = kappa * s
      var cx
      var cy
      if (Math.abs(kappa) < 1e-6) {
        cx = s
        cy = 0
      } else {
        cx = Math.sin(th) / kappa
        cy = (1 - Math.cos(th)) / kappa
      }
      var ct = Math.cos(th)
      var st = Math.sin(th)
      for (var q = 0; q < ox.length; q++) {
        var rx = ox[q] - cx
        var ry = oy[q] - cy
        var lx = ct * rx + st * ry
        var ly = -st * rx + ct * ry
        if (lx > -hl && lx < hl && ly > -hw && ly < hw) return Math.max(0, s - ds)
      }
    }
    return sMax
  }

  var prev = state.prevKappa || 0
  var best = null
  var bestCost = Infinity
  var bestHard = 0
  var bestFree = 0
  for (var a = 0; a < count; a++) {
    var kappa = count === 1 ? 0 : -kmax + (2 * kmax * a) / (count - 1)
    var fHard = freeLength(kappa, halfW, halfL)
    var fSoft = freeLength(kappa, halfW + soft - margin, halfL + soft - margin)
    var L = fHard
    var th = kappa * L
    var ex
    var ey
    if (Math.abs(kappa) < 1e-6) {
      ex = L
      ey = 0
    } else {
      ex = Math.sin(th) / kappa
      ey = (1 - Math.cos(th)) / kappa
    }
    var gdEnd = Math.sqrt((gx - ex) * (gx - ex) + (gy - ey) * (gy - ey))
    var progress = goalDist - gdEnd
    var bearing = Math.atan2(gy - ey, gx - ex)
    var herr = bearing - th
    while (herr > Math.PI) herr -= 2 * Math.PI
    while (herr < -Math.PI) herr += 2 * Math.PI
    var cost =
      -wProg * progress +
      wHead * Math.abs(herr) +
      wFree * (1 - L / H) +
      wSoft * (1 - Math.min(fSoft, H) / H) +
      wSmooth * (Math.abs(kappa - prev) / kmax)
    if (cost < bestCost) {
      bestCost = cost
      best = kappa
      bestHard = fHard
      bestFree = fSoft
    }
  }
  state.prevKappa = best
  av.plan = {
    kappa: best,
    free: bestHard,
    freeSoft: bestFree,
    blocked: bestHard < minFree,
    horizon: H,
    cost: bestCost,
  }
  api.watch('av.plan.kappa', Math.round(best * 1000) / 1000)
  api.watch('av.plan.free', Math.round(bestHard * 10) / 10)
  return {}
}

av_speed_planner.code:
// AV stack · PLAN / speed planner.
// v_des = min(cruise, stopping-distance limit, lateral-acceleration limit, goal approach).
// Publishes av.plan.vDesired.
// params: cruiseSpeed, comfortDecel, maxLatAccel, stopMargin, crawlSpeed, goalTolerance
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan) return {}
  var plan = av.plan
  var cruise = params.cruiseSpeed != null ? params.cruiseSpeed : 8
  var aBrake = params.comfortDecel || 5
  var aLat = params.maxLatAccel || 6
  var stopMargin = params.stopMargin != null ? params.stopMargin : 1.2
  var crawl = params.crawlSpeed != null ? params.crawlSpeed : 2
  var v = cruise
  var vFree = Math.sqrt(2 * aBrake * Math.max(0, plan.free - stopMargin))
  if (vFree < v) v = vFree
  var k = Math.abs(plan.kappa)
  if (k > 1e-4) {
    var vCurve = Math.sqrt(aLat / k)
    if (vCurve < v) v = vCurve
  }
  if (av.goal) {
    var tol = params.goalTolerance != null ? params.goalTolerance : 2.5
    var vGoal = Math.sqrt(2 * aBrake * Math.max(0, av.goal.dist - tol))
    if (vGoal < v) v = Math.max(vGoal, crawl)
  }
  if (!plan.blocked && v < crawl) v = crawl
  plan.vDesired = v
  return {}
}

av_supervisor.code:
// AV stack · PLAN / behaviour supervisor.
// Watches planner health and flags `av.needManeuver` when the local planner is blocked
// or the vehicle is stuck; holds at the final goal. Sets av.mode ('drive' | 'hold').
// Simulated time only. params: stuckTime, blockedTime, holdAtGoal, goalTolerance
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var plan = av.plan
  if (state.stuckT === undefined) {
    state.stuckT = 0
    state.blockedT = 0
  }
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var blockedTime = params.blockedTime != null ? params.blockedTime : 0.4
  var wantsMove = (plan.vDesired || 0) > 0.8
  if (wantsMove && Math.abs(e.speed) < 0.25) state.stuckT += dt
  else state.stuckT = 0
  if (plan.blocked && Math.abs(e.speed) < 1.2) state.blockedT += dt
  else state.blockedT = 0
  av.needManeuver = state.blockedT > blockedTime || state.stuckT > stuckTime
  av.mode = 'drive'
  var tol = params.goalTolerance != null ? params.goalTolerance : 2.5
  if (params.holdAtGoal !== false && av.goal && av.goal.dist < tol) {
    av.mode = 'hold'
    plan.vDesired = 0
    plan.kappa = 0
  }
  return {}
}

av_maneuver_planner.code:
// AV stack · PLAN / tight-space manoeuvre planner (Hybrid-A* over forward/reverse arc primitives).
// Activated by the supervisor (`av.needManeuver`). Searches (x, z, heading, gear) with a swept
// footprint check against the costmap, executes the resulting multi-point turn segment by segment
// and re-plans from the real pose after every segment. Hands back to the local planner as soon as it
// has a comfortable free path ahead.
// params: maneuverSpeed, primitiveLength, maxExpansions, gearSwitchPenalty, reversePenalty,
//         planMargin, tightMargin, guardMargin, stallTime, goalReach, handbackFree, maxCurvature, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego || !av.goal) return {}
  var e = av.ego
  var plan = av.plan
  var kmax = params.maxCurvature || 0.115
  var planMargin = params.planMargin != null ? params.planMargin : 0.4
  var tightMargin = params.tightMargin != null ? params.tightMargin : 0.1
  var guardMargin = params.guardMargin != null ? params.guardMargin : 0.15
  var ell = params.primitiveLength || 1.8
  var maxExp = params.maxExpansions || 4000
  var gearPen = params.gearSwitchPenalty != null ? params.gearSwitchPenalty : 4
  var revPen = params.reversePenalty != null ? params.reversePenalty : 1.6
  var reach = params.goalReach != null ? params.goalReach : 3.5
  var handback = params.handbackFree != null ? params.handbackFree : 10
  var vMan = params.maneuverSpeed != null ? params.maneuverSpeed : 3
  var ks = [-kmax, -kmax / 2, 0, kmax / 2, kmax]

  // spatial hash over costmap points + swept-footprint test (hl/hw are the active margins)
  function makeHit(pts, hlA, hwA) {
    var grid = {}
    for (var i = 0; i < pts.length; i++) {
      var key = Math.floor(pts[i][0] / 2) + ',' + Math.floor(pts[i][1] / 2)
      ;(grid[key] || (grid[key] = [])).push(pts[i])
    }
    var R = Math.sqrt(hlA * hlA + hwA * hwA)
    return function (x, z, fx, fz) {
      var x0 = Math.floor((x - R) / 2)
      var x1 = Math.floor((x + R) / 2)
      var z0 = Math.floor((z - R) / 2)
      var z1 = Math.floor((z + R) / 2)
      for (var cx = x0; cx <= x1; cx++) {
        for (var cz = z0; cz <= z1; cz++) {
          var list = grid[cx + ',' + cz]
          if (!list) continue
          for (var q = 0; q < list.length; q++) {
            var dx = list[q][0] - x
            var dz = list[q][1] - z
            var lx = dx * fx + dz * fz
            var ly = dx * fz - dz * fx
            if (lx > -hlA && lx < hlA && ly > -hwA && ly < hwA) return true
          }
        }
      }
      return false
    }
  }

  function search(sx, sz, sfx, sfz, gx, gz, pts) {
    var hlS = (params.vehicleLength || 4) / 2 + planMargin
    var hwS = (params.vehicleWidth || 2) / 2 + planMargin
    var hit = makeHit(pts, hlS, hwS)
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    if (hit(sx, sz, sfx, sfz)) {
      hlS = (params.vehicleLength || 4) / 2 + tightMargin
      hwS = (params.vehicleWidth || 2) / 2 + tightMargin
      hit = makeHit(pts, hlS, hwS)
    }
    function dist(x, z) {
      var dx = gx - x
      var dz = gz - z
      return Math.sqrt(dx * dx + dz * dz)
    }
    // binary min-heap on f
    var heap = []
    function push(nd) {
      heap.push(nd)
      var c = heap.length - 1
      while (c > 0) {
        var p = (c - 1) >> 1
        if (heap[p].f <= heap[c].f) break
        var t = heap[p]
        heap[p] = heap[c]
        heap[c] = t
        c = p
      }
    }
    function pop() {
      var top = heap[0]
      var last = heap.pop()
      if (heap.length > 0) {
        heap[0] = last
        var c = 0
        for (;;) {
          var l = 2 * c + 1
          var r = l + 1
          var m = c
          if (l < heap.length && heap[l].f < heap[m].f) m = l
          if (r < heap.length && heap[r].f < heap[m].f) m = r
          if (m === c) break
          var t = heap[m]
          heap[m] = heap[c]
          heap[c] = t
          c = m
        }
      }
      return top
    }
    function skey(x, z, fx, fz, g) {
      var ih = Math.round((Math.atan2(fz, fx) / (2 * Math.PI)) * 36)
      if (ih < 0) ih += 36
      return Math.round(x / 0.6) + ',' + Math.round(z / 0.6) + ',' + (ih % 36) + ',' + g
    }
    var HW = 1.4
    var start = { x: sx, z: sz, fx: sfx, fz: sfz, g: 0, gear: 0, k: 0, parent: null, f: dist(sx, sz) * HW, d: 0 }
    push(start)
    var best = {}
    best[skey(sx, sz, sfx, sfz, 0)] = 0
    var bestNode = start
    var bestH = dist(sx, sz)
    var goalNode = null
    var expansions = 0
    while (heap.length > 0 && expansions < maxExp) {
      var cur = pop()
      var ck = skey(cur.x, cur.z, cur.fx, cur.fz, cur.gear)
      if (best[ck] !== undefined && cur.g > best[ck] + 1e-6) continue
      expansions++
      var h = dist(cur.x, cur.z)
      if (h < bestH) {
        bestH = h
        bestNode = cur
      }
      if (h < reach) {
        goalNode = cur
        break
      }
      for (var gi = 0; gi < 2; gi++) {
        var gear = gi === 0 ? 1 : -1
        for (var ki = 0; ki < ks.length; ki++) {
          var k = ks[ki]
          var lx = cur.fz
          var lz = -cur.fx
          var ok = true
          var nx = cur.x
          var nz = cur.z
          var nfx = cur.fx
          var nfz = cur.fz
          for (var sIdx = 1; sIdx <= 4; sIdx++) {
            var d = (gear * ell * sIdx) / 4
            var th = k * d
            var ddx
            var ddy
            if (Math.abs(k) < 1e-6) {
              ddx = d
              ddy = 0
            } else {
              ddx = Math.sin(th) / k
              ddy = (1 - Math.cos(th)) / k
            }
            nx = cur.x + cur.fx * ddx + lx * ddy
            nz = cur.z + cur.fz * ddx + lz * ddy
            var ct = Math.cos(th)
            var st = Math.sin(th)
            nfx = cur.fx * ct + lx * st
            nfz = cur.fz * ct + lz * st
            if (hit(nx, nz, nfx, nfz)) {
              ok = false
              break
            }
          }
          if (!ok) continue
          var step = ell * (gear < 0 ? revPen : 1) + (Math.abs(k) / kmax) * 0.4 * ell
          if (cur.gear !== 0 && cur.gear !== gear) step += gearPen
          if (cur.gear !== 0 && cur.k !== k) step += 0.3
          var g2 = cur.g + step
          var nk = skey(nx, nz, nfx, nfz, gear)
          if (best[nk] !== undefined && best[nk] <= g2) continue
          best[nk] = g2
          push({ x: nx, z: nz, fx: nfx, fz: nfz, g: g2, gear: gear, k: k, parent: cur, f: g2 + dist(nx, nz) * HW })
        }
      }
    }
    var end = goalNode || bestNode
    var segs = []
    for (var nd = end; nd && nd.parent; nd = nd.parent) {
      var last = segs[0]
      if (last && last.g === nd.gear && last.k === nd.k) {
        last.len += ell
      } else {
        segs.unshift({ g: nd.gear, k: nd.k, len: ell, end: null })
      }
    }
    // expected pose at the end of every segment (walk the chain again, front to back)
    var chain = []
    for (var cn = end; cn; cn = cn.parent) chain.unshift(cn)
    var si = -1
    var prevG = null
    var prevK = null
    for (var ci = 1; ci < chain.length; ci++) {
      var nn = chain[ci]
      if (si < 0 || nn.gear !== prevG || nn.k !== prevK) {
        si++
        prevG = nn.gear
        prevK = nn.k
      }
      segs[si].end = { x: nn.x, z: nn.z, fx: nn.fx, fz: nn.fz }
    }
    return { segs: segs, reached: !!goalNode, expansions: expansions, hRemaining: bestH }
  }

  function begin(res) {
    state.segs = res.segs
    state.idx = 0
    state.segStart = null
    state.prevGear = 0
    state.exp = res.expansions
  }
  function deviates(seg) {
    if (!seg || !seg.end) return false
    var ex = input.position[0] - seg.end.x
    var ez = input.position[2] - seg.end.z
    var dot = e.fwd[0] * seg.end.fx + e.fwd[2] * seg.end.fz
    return Math.sqrt(ex * ex + ez * ez) > 0.9 || dot < 0.97
  }

  if (!state.active) {
    if (!av.needManeuver) return {}
    var res = search(input.position[0], input.position[2], e.fwd[0], e.fwd[2], av.goal.x, av.goal.z, av.points || [])
    if (res.segs.length === 0) return {}
    state.active = true
    state.replans = (state.replans || 0) + 1
    begin(res)
  }

  // --- execute ---
  var cur = state.segs[state.idx]
  if (state.segStart === null) {
    // a gear change must come to rest first so the odometer does not count coasting
    if (cur.g === state.prevGear || Math.abs(e.speed) < 0.4) state.segStart = [input.position[0], input.position[2]]
  }
  var travelled = 0
  if (state.segStart) {
    var dx = input.position[0] - state.segStart[0]
    var dz = input.position[2] - state.segStart[1]
    travelled = Math.sqrt(dx * dx + dz * dz)
  }
  // --- execution guard: re-plan when the real pose makes the rest of the segment collide, or when stalled ---
  if (state.segStart !== null) {
    var guardL = (params.vehicleLength || 4) / 2 + guardMargin
    var guardW = (params.vehicleWidth || 2) / 2 + guardMargin
    var gHit = makeHit(av.points || [], guardL, guardW)
    var lx0 = e.left[0]
    var lz0 = e.left[2]
    var look = Math.min(2.0, Math.max(0, cur.len - travelled))
    var blockedAhead = false
    for (var gd = 0.5; gd <= look + 1e-6 && !blockedAhead; gd += 0.5) {
      var gdd = cur.g * gd
      var gth = cur.k * gdd
      var gx2 = Math.abs(cur.k) < 1e-6 ? gdd : Math.sin(gth) / cur.k
      var gy2 = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(gth)) / cur.k
      var px = input.position[0] + e.fwd[0] * gx2 + lx0 * gy2
      var pz = input.position[2] + e.fwd[2] * gx2 + lz0 * gy2
      var pfx = e.fwd[0] * Math.cos(gth) + lx0 * Math.sin(gth)
      var pfz = e.fwd[2] * Math.cos(gth) + lz0 * Math.sin(gth)
      if (gHit(px, pz, pfx, pfz)) blockedAhead = true
    }
    state.stallT = Math.abs(e.speed) < 0.15 ? (state.stallT || 0) + dt : 0
    var stallTime = params.stallTime != null ? params.stallTime : 1.2
    if ((blockedAhead || state.stallT > stallTime) && e.t - (state.lastReplanT || -9) > 0.6) {
      var fix = search(input.position[0], input.position[2], e.fwd[0], e.fwd[2], av.goal.x, av.goal.z, av.points || [])
      state.lastReplanT = e.t
      state.stallT = 0
      state.replans++
      if (fix.segs.length > 0) {
        begin(fix)
        state.prevGear = cur.g
        cur = state.segs[0]
        travelled = 0
      }
    }
  }
  var finished = state.segStart !== null && travelled >= cur.len - 0.25
  var handbackOk = plan.free >= handback && state.idx > 0 && (cur.g > 0 || Math.abs(e.speed) < 0.3)
  if (handbackOk) {
    state.active = false
    return {}
  }
  if (finished) {
    state.prevGear = cur.g
    if (state.idx + 1 >= state.segs.length || deviates(cur)) {
      var again = search(input.position[0], input.position[2], e.fwd[0], e.fwd[2], av.goal.x, av.goal.z, av.points || [])
      state.replans++
      if (again.segs.length === 0) {
        state.active = false
        return {}
      }
      begin(again)
      state.prevGear = cur.g
    } else {
      state.idx++
      state.segStart = null
    }
    cur = state.segs[state.idx]
    travelled = 0
  }
  var remain = state.segStart ? Math.max(0, cur.len - travelled) : cur.len
  var vMax = Math.min(vMan, 0.9 + Math.sqrt(2 * 3 * remain))
  var wrongWay = state.segStart === null || cur.g * e.speed < -0.35
  plan.kappa = cur.k
  plan.vDesired = wrongWay ? 0 : cur.g * vMax
  plan.maneuver = true
  av.mode = 'maneuver'
  api.watch('av.maneuver', 'seg ' + state.idx + '/' + state.segs.length + ' g' + cur.g + ' k' + cur.k.toFixed(3) + ' replans ' + state.replans)
  return {}
}

av_control_lateral.code:
// AV stack · CONTROL / lateral (curvature tracking).
// steering = feed-forward(kappa_plan / kappaPerSteer) + P feedback on measured curvature,
// with a steering-rate limiter (comfort / actuator model).
// params: kappaPerSteer, fbGain, steerRate
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var kps = params.kappaPerSteer || 0.12
  var fb = params.fbGain != null ? params.fbGain : 0.35
  var rate = params.steerRate != null ? params.steerRate : 4
  var kCmd = av.plan.kappa
  var steer = kCmd / kps
  if (Math.abs(e.speed) > 2 && av.mode !== 'reverse') {
    steer += (fb * (kCmd - e.kappa)) / kps
  }
  if (steer > 1) steer = 1
  if (steer < -1) steer = -1
  var prev = state.steer || 0
  var maxStep = rate * dt
  if (steer > prev + maxStep) steer = prev + maxStep
  if (steer < prev - maxStep) steer = prev - maxStep
  state.steer = steer
  // car2 treats exactly 0 as "no steering command" (wheel re-centres on its own)
  input.actions.steering_angle = Math.abs(steer) < 1e-4 ? 0 : steer
  av.cmdSteer = steer
  return {}
}

av_control_longitudinal.code:
// AV stack · CONTROL / longitudinal (speed PI with deadband feed-forward).
// The actuator has a static-friction deadband, so the controller adds `deadband` as feed-forward
// and PI-trims on top. Negative demand maps to the car's `brake` input (reverse thrust at standstill).
// params: kp, ki, deadband, maxThrottle, maxBrake, brakeGain
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var vDes = av.plan.vDesired || 0
  var kp = params.kp != null ? params.kp : 0.03
  var ki = params.ki != null ? params.ki : 0.02
  var db = params.deadband != null ? params.deadband : 0.36
  var maxThr = params.maxThrottle != null ? params.maxThrottle : 0.46
  var maxBrk = params.maxBrake != null ? params.maxBrake : 0.6
  var brakeGain = params.brakeGain != null ? params.brakeGain : 0.12
  // signed demand: positive = forward drive (throttle), negative = reverse drive (brake channel)
  var dir = vDes >= 0 ? 1 : -1
  var vAlong = e.speed * dir // speed in the demanded direction
  var vTarget = Math.abs(vDes)
  var err = vTarget - vAlong
  var thr = 0
  var brk = 0
  var drive = 0 // magnitude along the demanded direction
  var retard = 0 // magnitude opposing motion in the demanded direction
  if (vTarget < 0.05 && Math.abs(e.speed) < 0.3) {
    state.i = 0
  } else if (err > 0) {
    state.i = Math.min(0.1, (state.i || 0) + ki * err * dt)
    drive = Math.min(maxThr, db + kp * err + state.i)
  } else {
    state.i = Math.max(0, (state.i || 0) * 0.9)
    retard = Math.min(maxBrk, brakeGain * -err)
    if (vAlong < 0.3 && vTarget < 0.05) retard = 0
  }
  if (vTarget < 0.05 && Math.abs(e.speed) >= 0.3) {
    // demand zero but still rolling: brake against the current direction of travel
    var oppose = e.speed > 0 ? 1 : -1
    var b = Math.min(maxBrk, brakeGain * Math.abs(e.speed))
    if (oppose > 0) brk = b
    else thr = b
  } else if (dir > 0) {
    thr = drive
    brk = retard
  } else {
    brk = drive
    thr = retard
  }
  input.actions.throttle = thr
  input.actions.brake = brk
  av.cmd = { throttle: thr, brake: brk }
  return {}
}

av_aeb.code:
// AV stack · SAFETY / autonomous emergency braking (independent monitor, own sensing).
// Runs after control and may only reduce throttle / add brake. Uses a smaller margin while the manoeuvre planner is driving (it already keeps swept clearance).
// params: aebDecel, aebMargin, aebHalfWidth
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  if (e.speed < 0.8) {
    av.aeb = false
    return {}
  }
  var a = params.aebDecel || 7
  var margin = params.aebMargin != null ? params.aebMargin : 1.0
  if (av.mode === 'maneuver') margin = 0.2
  var hw = params.aebHalfWidth != null ? params.aebHalfWidth : 0.9
  var need = (e.speed * e.speed) / (2 * a) + margin
  var origin = api.vec.offsetAlong(input.position, e.fwd, 2.3)
  var hit = api.raycastSpread(origin, e.fwd, need + 1, hw, 5, { visualize: false })
  av.aeb = false
  if (hit.hit && hit.distance < need) {
    av.aeb = true
    input.actions.throttle = 0
    var b = Math.min(1, 0.3 + (need - hit.distance) / need)
    if (b > (input.actions.brake || 0)) input.actions.brake = b
    api.watch('av.aeb', hit.distance)
  }
  return {}
}
